  "user_query": "First bring me to Room 3117 and then to the elevator on the 3rd floor.",
  "targets": [
    {
      "order": 0,
      "intent": "navigation_guidance",
      "target_type": "explicit",
      "filter": "name LIKE '%3117%'",
      "semantics": "Room 3117",
      "source": "LLM"
