      "order": 1,
      "intent": "navigation_guidance",
      "target_type": "explicit",
      "filter": "name LIKE '%Elevator%' AND parentName LIKE '%3rd Floor%'",
      "semantics": "elevator, lift, 3rd floor",
      "source": "LLM"
